{
  "name": "USB4000/USB2000+光谱仪",
  "name_en": "USB4000/USB2000+ spectrometer",
  "manufacturer": "Ocean Insight",
  "description": "Ocean Insight 的 USB4000/USB2000+ 系列光谱仪，用于实验室中的光谱采集与光学信号测量。该设备通过 USB 通信，可读取光谱数据、设置积分时间，并查询采集请求与光谱就绪状态，适用于吸收、发射或一般光谱分析实验。",
  "description_en": "An Ocean Insight USB4000/USB2000+ series spectrometer for laboratory spectral acquisition and optical signal measurement. It communicates over USB, can read spectral data, set integration time, and report acquisition-request and spectrum-ready states for absorption, emission, or general spectroscopy workflows.",
  "actions": [
    {
      "action_name": "auto-doInitializeDevice",
      "description": "初始化光谱仪设备并建立 USB 通信。",
      "description_en": "Initialize the spectrometer and establish USB communication."
    },
    {
      "action_name": "auto-getSpectrumData",
      "description": "获取当前采集完成后的光谱数据。",
      "description_en": "Retrieve spectral data from the completed acquisition."
    },
    {
      "action_name": "auto-setIntegrationTime",
      "description": "设置光谱采集的积分时间（毫秒）。",
      "description_en": "Set the integration time for spectral acquisition in milliseconds."
    },
    {
      "action_name": "auto-isSpectrumRequested",
      "description": "查询是否已发出光谱采集请求且设备仍在等待采集完成。",
      "description_en": "Check whether a spectrum acquisition has been requested and the device is still waiting for completion."
    },
    {
      "action_name": "auto-isSpectrumReady",
      "description": "查询请求的光谱是否已准备好读取。",
      "description_en": "Check whether the requested spectrum is ready to be retrieved."
    }
  ],
  "tag_hints": [
    "optical spectroscopy",
    "USB spectrometer",
    "Ocean Insight",
    "spectral acquisition",
    "integration time control",
    "wavelength measurement"
  ]
}

